const base = $('Fusion client + choix recherche devis').all();
const res = $input.all();
const STATUS = { paid: 'paye', signed: 'signe', sent: 'envoye', draft: 'brouillon', refused: 'refuse', expired: 'expire', billed: 'facture' };
return base.map((b, i) => {
  const j = Object.assign({}, b.json);
  const r = res[i] ? res[i].json : null;
  const list = (r && r.ok && r.data && Array.isArray(r.data.items)) ? r.data.items : [];
  j.quoteId = '';
  j.quoteStatus = '';
  j.quoteNote = '';
  if (j.quoteMode === 'ref') {
    const exact = list.filter(q => String(q.reference || '').toUpperCase() === j.quoteRef);
    if (exact.length === 1) { j.quoteId = exact[0].id; j.quoteStatus = STATUS[exact[0].status] || exact[0].status || ''; }
    else if (exact.length === 0) j.quoteNote = 'Devis ' + j.quoteRef + ' introuvable dans Interfast';
    else j.quoteNote = 'Plusieurs devis portent la reference ' + j.quoteRef;
  } else if (j.quoteMode === 'fallback') {
    const signed = list.filter(q => q.signedAt);
    const cands = signed.map(q => String(q.reference || '?') + ' (' + (STATUS[q.status] || q.status || '?') + (q.name ? ', ' + q.name : '') + ')');
    j.quoteNote = signed.length
      ? 'Pas de n de devis sur le RDV. Devis signes du client : ' + cands.join(' ; ')
      : 'Pas de n de devis sur le RDV, et aucun devis signe pour ce client';
  }
  j.path = j.quoteId ? '/v1/billing/quotations/' + j.quoteId : '';
  j.query = {};
  return { json: j };
});

const base = $('Choix devis').all();
const res = $input.all();
const CHAT_ID = '1857340429';
const MAX = 3800;
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function cap(s) { s = String(s || ''); return s.charAt(0).toUpperCase() + s.slice(1); }
function stripHtml(h) {
  return String(h || '')
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&eacute;/g, 'e')
    .trim();
}
function itemTitle(it) {
  const m = String(it.name || '').match(/<strong>([\s\S]*?)<\/strong>/i);
  let t = m ? stripHtml(m[1]) : stripHtml(it.name).split('\n')[0];
  t = t.replace(/\s+/g, ' ').trim();
  if (t.length > 80) t = t.slice(0, 77) + '...';
  return t;
}
const SKIP = /^(pose|mise en service|main d|deplacement|d[ée]placement|forfait pose)/i;
const rows = base.map((b, i) => {
  const j = Object.assign({}, b.json);
  const r = res[i] ? res[i].json : null;
  const q = (r && r.ok && r.data) ? r.data : null;
  j.material = [];
  j.quoteName = '';
  if (q) {
    j.quoteName = String(q.name || '').trim();
    for (const it of (q.items || [])) {
      const t = itemTitle(it);
      if (!t || SKIP.test(t)) continue;
      const qty = (it.quantity && Number(it.quantity) !== 1) ? it.quantity + ' x ' : '';
      const ref = it.reference ? ' [' + String(it.reference).trim() + ']' : '';
      j.material.push(qty + t + ref);
    }
  }
  return j;
});
if (rows.length === 1 && rows[0].empty) {
  return [{ json: { chatId: CHAT_ID, text: '<b>Brief ClimatPro</b>\nAucune intervention planifiee pour demain.' } }];
}
function block(r, tn) {
  const o = [];
  o.push('<b>' + esc(r.timeLabel) + '</b> - ' + esc(r.clientName) + (r.city ? ', ' + esc(r.city) : '') + ' - ' + esc(r.reference));
  if (r.type) o.push(esc(r.type));
  if (r.title && r.title !== r.type) o.push('Titre : ' + esc(r.title));
  const others = r.techs.filter(t => t.name !== tn).map(t => t.name);
  if (others.length) o.push('Avec : ' + esc(others.join(', ')));
  if (r.address) o.push(esc(r.address));
  if (r.addrLine2) o.push('Acces : ' + esc(r.addrLine2));
  if (r.addrComments) o.push('Acces : ' + esc(r.addrComments));
  if (r.phones && r.phones.length) o.push('Tel : ' + esc(r.phones.join(' / ')));
  if (r.clientComment) o.push('Client : ' + esc(r.clientComment));
  if (r.description) o.push('Note : ' + esc(r.description));
  if (r.isMaintenance) {
    o.push('Visite de maintenance sous contrat');
  } else if (r.quoteId) {
    o.push('Devis ' + esc(r.quoteRef) + (r.quoteStatus ? ' (' + esc(r.quoteStatus) + ')' : '') + (r.quoteName ? ' - ' + esc(r.quoteName) : ''));
    if (r.material.length) o.push('Materiel :\n- ' + r.material.map(esc).join('\n- '));
    else o.push('Materiel : aucune ligne lisible dans le devis');
  } else if (r.quoteNote) {
    o.push('Devis : ' + esc(r.quoteNote));
  }
  return o;
}
const byDate = {};
for (const r of rows) {
  const key = r.timeMode === 'acaler' ? 'ZZ' : r.dateKey;
  (byDate[key] = byDate[key] || []).push(r);
}
const lines = [];
const keys = Object.keys(byDate).sort();
for (const k of keys) {
  const list = byDate[k];
  if (lines.length) lines.push('');
  lines.push(k === 'ZZ' ? '<b>A caler (date non fixee)</b>' : '<b>Brief ClimatPro - ' + esc(cap(list[0].dateLabel)) + '</b>');
  const byTech = {};
  for (const r of list) {
    const p = r.techs.find(t => t.id === r.primaryTechId) || r.techs[0] || { id: 0, name: 'Non affecte' };
    (byTech[p.name] = byTech[p.name] || []).push(r);
  }
  for (const tn of Object.keys(byTech).sort()) {
    lines.push('');
    lines.push('<u><b>' + esc(tn) + '</b></u> - ' + byTech[tn].length + ' intervention' + (byTech[tn].length > 1 ? 's' : ''));
    for (const r of byTech[tn]) {
      lines.push('');
      for (const l of block(r, tn)) lines.push(l);
    }
  }
}
const messages = [];
let cur = '';
for (const l of lines) {
  const next = cur ? cur + '\n' + l : l;
  if (next.length > MAX && cur) { messages.push(cur); cur = l; } else { cur = next; }
}
if (cur) messages.push(cur);
return messages.map(t => ({ json: { chatId: CHAT_ID, text: t } }));

const now = $now.setZone('Europe/Paris');
const dayStart = now.plus({ days: 1 }).startOf('day');
let dayEnd = dayStart.endOf('day');
if (dayStart.weekday === 6) dayEnd = dayStart.plus({ days: 2 }).endOf('day');
if (dayStart.weekday === 7) dayEnd = dayStart.plus({ days: 1 }).endOf('day');
return [{ json: {
  path: '/v1/events',
  query: {
    start: dayStart.toUTC().toISO(),
    end: dayEnd.toUTC().toISO(),
    archived: false,
    meeting: false,
    page: 0,
    count: 100
  },
  windowStart: dayStart.toISO(),
  windowEnd: dayEnd.toISO()
} }];

const base = $('Fusion detail').all();
const res = $input.all();
function fmtPhone(p) {
  if (!p) return '';
  let s = String(p).replace(/[\s.-]/g, '');
  if (s.startsWith('+33')) s = '0' + s.slice(3);
  return s.replace(/(\d{2})(?=\d)/g, '$1 ').trim();
}
function short(s, max) {
  s = String(s || '').replace(/\s+/g, ' ').trim();
  if (s.length > max) s = s.slice(0, max - 3) + '...';
  return s;
}
return base.map((b, i) => {
  const j = Object.assign({}, b.json);
  const r = res[i] ? res[i].json : null;
  const c = (r && r.ok && r.data) ? r.data : null;
  j.phones = [];
  j.clientComment = '';
  if (c) {
    const cp = c.clientParticular || c.clientProfessional || c.clientOwnersAssociation || {};
    const main = cp.contact || {};
    const seen = new Set();
    function addPhone(num, info) {
      const f = fmtPhone(num);
      if (!f || seen.has(f)) return;
      seen.add(f);
      j.phones.push(f + (info ? ' (' + info + ')' : ''));
    }
    addPhone(main.phoneNumber, short(main.comment, 60));
    addPhone(main.secondaryPhoneNumber, '');
    for (const ct of (cp.contacts || [])) {
      const nm = [ct.firstName, ct.lastName].filter(Boolean).join(' ').trim();
      addPhone(ct.phoneNumber, short([nm, ct.comment].filter(Boolean).join(', '), 60));
    }
    j.clientComment = short(c.commentary, 300);
  }
  j.description = short(j.description, 300);
  const mref = String(j.secondReference || '').match(/\b(DC\s*\d{3,})\b/i);
  j.quoteRef = mref ? mref[1].replace(/\s+/g, '').toUpperCase() : '';
  if (j.quoteRef) {
    j.quoteMode = 'ref';
    j.path = '/v1/billing/quotations';
    j.query = { name: j.quoteRef, page: 0, size: 10 };
  } else if (!j.isMaintenance && j.clientId) {
    j.quoteMode = 'fallback';
    j.path = '/v1/billing/quotations';
    j.query = { clients: [j.clientId], page: 0, size: 20, orderBy: 'updatedAt', isDesc: true };
  } else {
    j.quoteMode = 'none';
    j.path = '';
    j.query = {};
  }
  return { json: j };
});

const base = $('Interventions').all();
const det = $input.all();
return base.map((b, i) => {
  const j = Object.assign({}, b.json);
  const r = det[i] ? det[i].json : null;
  const d = (r && r.ok && r.data) ? r.data : null;
  j.description = '';
  j.addrLine2 = '';
  j.addrComments = '';
  if (d) {
    j.description = String(d.description || '').trim();
    if (d.address) {
      j.addrLine2 = String(d.address.additionalLine || '').replace(/\s+/g, ' ').trim();
      j.addrComments = String(d.address.comments || '').replace(/\s+/g, ' ').trim();
    }
  }
  j.path = j.clientId ? '/v1/client/' + j.clientId : '';
  j.query = {};
  return { json: j };
});

const res = $input.first().json;
const items = (res && res.data && Array.isArray(res.data.items)) ? res.data.items : [];
const TZ = 'Europe/Paris';
function decode(dt) {
  const d = dt.minute % 10;
  const hhmm = dt.toFormat('H') + 'h' + dt.toFormat('mm');
  if (d === 1) return { label: hhmm + ' (approx., +/- 30 min)', mode: 'approx' };
  if (d === 2) return { label: (dt.hour < 12 ? 'Matin' : 'Apres-midi') + ' (demi-journee)', mode: 'demi' };
  if (d === 3) return { label: 'Journee entiere', mode: 'journee' };
  if (d === 4) return { label: 'Date non fixee (RDV valide)', mode: 'acaler' };
  return { label: hhmm, mode: 'fixe' };
}
const out = [];
for (const ev of items) {
  if (ev.category !== 'intervention') continue;
  if (ev.finished || ev.lifecycleState === 'cancelled') continue;
  const seen = new Set();
  const techs = [];
  for (const u of (ev.users || [])) {
    if (!seen.has(u.id)) { seen.add(u.id); techs.push({ id: u.id, name: u.firstName || u.lastName || ('#' + u.id) }); }
  }
  const start = DateTime.fromISO(ev.start, { zone: 'utc' }).setZone(TZ);
  const t = decode(start);
  const addr = ev.address || '';
  const m = addr.match(/(\d{5})\s+(.+)$/);
  out.push({ json: {
    id: ev.id,
    reference: ev.reference || '',
    title: ev.title || '',
    type: ev.type || '',
    startIso: ev.start,
    dateKey: start.toFormat('yyyy-LL-dd'),
    dateLabel: start.setLocale('fr').toFormat('cccc d LLLL'),
    sortKey: start.toMillis(),
    timeLabel: t.label,
    timeMode: t.mode,
    clientId: ev.client ? ev.client.id : null,
    clientName: ev.client ? ev.client.name : '?',
    address: addr,
    city: m ? m[2] : '',
    priority: ev.priority || '',
    primaryTechId: ev.primaryTechnicianId,
    techs: techs,
    secondReference: String(ev.secondReference || '').trim(),
    isMaintenance: !!ev.maintenance,
    path: '/v1/intervention/' + ev.id,
    query: { withFollowUp: false }
  } });
}
out.sort((a, b) => a.json.sortKey - b.json.sortKey);
if (out.length === 0) return [{ json: { empty: true, path: '', query: {} } }];
return out;
